"""Patches the Android project generated by `flutter create` so that
audio background playback, notifications and permissions work.
Runs inside GitHub Actions (or locally: python3 tools/patch_android.py)."""
import glob
import re
import sys

ok = True

# ---------- 1. AndroidManifest.xml ----------
mp = "android/app/src/main/AndroidManifest.xml"
m = open(mp, encoding="utf-8").read()

if "xmlns:tools" not in m:
    m = m.replace("<manifest ", '<manifest xmlns:tools="http://schemas.android.com/tools" ', 1)

perms = """
    <uses-permission android:name="android.permission.INTERNET"/>
    <uses-permission android:name="android.permission.WAKE_LOCK"/>
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE"/>
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK"/>
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS"/>
    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED"/>
"""
if "FOREGROUND_SERVICE_MEDIA_PLAYBACK" not in m:
    m = re.sub(r"(<manifest[^>]*>)", lambda x: x.group(1) + perms, m, count=1)

services = """
        <service android:name="com.ryanheise.audioservice.AudioService"
            android:foregroundServiceType="mediaPlayback"
            android:exported="true" tools:ignore="Instantiatable">
            <intent-filter>
                <action android:name="android.media.browse.MediaBrowserService"/>
            </intent-filter>
        </service>
        <receiver android:name="com.ryanheise.audioservice.MediaButtonReceiver"
            android:exported="true" tools:ignore="Instantiatable">
            <intent-filter>
                <action android:name="android.intent.action.MEDIA_BUTTON"/>
            </intent-filter>
        </receiver>
"""
if "com.ryanheise.audioservice.AudioService" not in m:
    m = m.replace("</application>", services + "    </application>", 1)

m = re.sub(r'android:label="[^"]*"', 'android:label="Surah Yaseen"', m, count=1)
open(mp, "w", encoding="utf-8").write(m)
print("Manifest patched")

# ---------- 2. MainActivity -> AudioServiceActivity ----------
acts = glob.glob("android/app/src/main/**/MainActivity.*", recursive=True)
if not acts:
    print("ERROR: MainActivity not found"); ok = False
for a in acts:
    s = open(a, encoding="utf-8").read()
    s = s.replace("io.flutter.embedding.android.FlutterActivity",
                  "com.ryanheise.audioservice.AudioServiceActivity")
    s = s.replace("FlutterActivity", "AudioServiceActivity")
    open(a, "w", encoding="utf-8").write(s)
    print("Patched", a)

# ---------- 3. Gradle: core library desugaring ----------
gk = "android/app/build.gradle.kts"
gg = "android/app/build.gradle"
DESUGAR = "2.1.4"
if glob.glob(gk):
    s = open(gk, encoding="utf-8").read()
    if "isCoreLibraryDesugaringEnabled" not in s:
        s = re.sub(r"compileOptions\s*\{",
                   "compileOptions {\n        isCoreLibraryDesugaringEnabled = true", s, count=1)
        s += '\ndependencies {\n    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:%s")\n}\n' % DESUGAR
    open(gk, "w", encoding="utf-8").write(s)
    print("Gradle (kts) patched")
elif glob.glob(gg):
    s = open(gg, encoding="utf-8").read()
    if "coreLibraryDesugaringEnabled" not in s:
        s = re.sub(r"compileOptions\s*\{",
                   "compileOptions {\n        coreLibraryDesugaringEnabled true", s, count=1)
        s += "\ndependencies {\n    coreLibraryDesugaring 'com.android.tools:desugar_jdk_libs:%s'\n}\n" % DESUGAR
    open(gg, "w", encoding="utf-8").write(s)
    print("Gradle (groovy) patched")
else:
    print("ERROR: build.gradle not found"); ok = False

sys.exit(0 if ok else 1)
